                isAccountUpdate = true;
            }
            if (type == "MP")
            {
                this.handleMarkPrice(client, (Dictionary<string, object>)message);
            } else if (inOp(data, "f"))
            {
                this.handleFundingRate(client, message);
            } else if (!isAccountUpdate)
            {
                this.handleOrderBook(client, message);
            }
        }
    }
